let state, page = "dashboard", analytics = null, reportError = null, reportType = "month", reportPeriod = new Date().toISOString().slice(0, 7), backups = null, billHistory = null, inventoryData = null, inventoryError = null, inventoryFilters = {};
const $ = s => document.querySelector(s);
const money = n => new Intl.NumberFormat("th-TH", { style:"currency", currency:"THB", minimumFractionDigits:0, maximumFractionDigits:0 }).format(Math.ceil(Number(n) || 0));
const time = s => new Date(s).toLocaleTimeString("th-TH", { hour:"2-digit", minute:"2-digit" });
const duration = n => `${String(Math.floor(n / 3600)).padStart(2,"0")}:${String(Math.floor(n % 3600 / 60)).padStart(2,"0")}:${String(n % 60).padStart(2,"0")}`;
async function api(url, options = {}) { const r = await fetch(url, { headers:{ "Content-Type":"application/json" }, ...options }); const contentType=r.headers.get("content-type")||"", isJson=contentType.includes("application/json"); let data; try { data=isJson ? await r.json() : await r.text(); } catch { data=null; } if (!r.ok) { const inventoryEndpoint=url.startsWith("/api/products")||url.startsWith("/api/product-categories"); const message=!isJson&&inventoryEndpoint ? "ไม่พบ API สำหรับจัดการสินค้า กรุณาตรวจสอบว่าเซิร์ฟเวอร์เป็นเวอร์ชันล่าสุด" : (isJson&&data?.error ? data.error : "ไม่สามารถติดต่อ API ได้"); const error=Error(message); error.status=r.status; throw error; } if (!isJson) { const error=Error("API ตอบกลับข้อมูลไม่ถูกต้อง กรุณาตรวจสอบเซิร์ฟเวอร์"); error.status=r.status; throw error; } return data; }
async function refresh() { try { state = await api("/api/state"); if(state.user.mustChangePassword) return showPasswordChange(); render(); } catch(error) { if(error.status===401) return showLogin(); throw error; } }
function bindPasswordVisibility(toggleId, formId){const toggle=$(toggleId),form=$(formId);toggle.onchange=()=>form.querySelectorAll('input[name="currentPassword"],input[name="password"],input[data-password-field]').forEach(input=>input.type=toggle.checked?"text":"password");}
function showPasswordChange(){ document.querySelector("aside").style.display="none"; document.querySelector("main").innerHTML=`<div id="app"><div class="card form" style="max-width:420px;margin:10vh auto"><h2>เปลี่ยนรหัสผ่าน</h2><p class="muted">บัญชีนี้ต้องเปลี่ยนรหัสผ่านก่อนใช้งาน</p><form id="passwordForm"><label>รหัสผ่านเดิม</label><input name="currentPassword" type="password" required><label>รหัสผ่านใหม่</label><input name="password" type="password" minlength="8" required><small>รหัสผ่านต้องมีความยาวอย่างน้อย 8 ตัว</small><label class="password-toggle"><input id="showForcedPasswords" type="checkbox"> แสดงรหัสผ่าน</label><button>บันทึกรหัสผ่านใหม่</button></form></div></div>`; bindPasswordVisibility("#showForcedPasswords","#passwordForm"); $("#passwordForm").onsubmit=async event=>{event.preventDefault();try{await api(`/api/users/${state.user.userId}/password`,{method:"PATCH",body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});location.reload();}catch(error){notify(error.message,true);}}; }
function showLogin(){ document.querySelector("aside").style.display="none"; document.querySelector("main").innerHTML=`<div id="app"><div class="card form" style="max-width:420px;margin:10vh auto"><h2>เข้าสู่ระบบ</h2><form id="loginForm"><label>ชื่อผู้ใช้</label><input name="username" autocomplete="username" required><label>รหัสผ่าน</label><input id="loginPassword" name="password" type="password" autocomplete="current-password" required><label class="password-toggle"><input id="showLoginPassword" type="checkbox"> แสดงรหัสผ่าน</label><button>เข้าสู่ระบบ</button></form><p class="muted">บัญชีเริ่มต้น: admin — โปรดเปลี่ยนรหัสผ่านทันทีหลังเข้าใช้งานครั้งแรก</p></div></div>`; $("#showLoginPassword").onchange=event=>$("#loginPassword").type=event.target.checked?"text":"password"; $("#loginForm").onsubmit=async event=>{event.preventDefault(); try{await api("/api/auth/login",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(event.target)))}); document.querySelector("aside").style.display=""; location.reload();}catch(error){notify(error.message,true);}}; }
function notify(text, bad = false) { const t = $("#toast"); t.textContent = text; t.style.background = bad ? "#991b1b" : "#166534"; t.style.opacity = 1; setTimeout(() => t.style.opacity = 0, 2600); }
function nav() { document.querySelectorAll("aside button[data-page]").forEach(b => b.onclick = async () => { page = b.dataset.page; if (page === "reports") await loadAnalytics(); if (page === "settings") await loadBackups(); if (page === "bills") await loadBillHistory(); render(); }); $("#refresh").onclick = refresh; $("#logout").onclick=async()=>{await api("/api/auth/logout",{method:"POST"}); state=null; showLogin();}; }
async function loadBackups() { try { backups = await api("/api/backups"); } catch (e) { notify(e.message, true); } }
function render() { if (!state) return; const names={dashboard:"ภาพรวม",tables:"โต๊ะสนุกเกอร์",pos:"POS อาหาร/เครื่องดื่ม",members:"สมาชิก",bills:"ประวัติบิล",reports:"รายงานและสถิติ",settings:"ตั้งค่าร้าน"}; $("#title").textContent=names[page]; $("#clock").textContent=new Date().toLocaleString("th-TH"); $("#currentUser").textContent=`${state.user.displayName} (${state.user.role})`; const pages={dashboard,tables,pos,members,bills,reports,settings}; $("#app").innerHTML=pages[page](); bind(); }
function dashboard(){ const paid=state.bills.filter(b=>b.status==="paid"&&b.createdAt.slice(0,10)===new Date().toISOString().slice(0,10)); const total=paid.reduce((s,b)=>s+b.total,0); return `<div class="grid"><div class="card"><div class="muted">รายได้วันนี้</div><div class="stat">${money(total)}</div></div><div class="card"><div class="muted">โต๊ะกำลังเล่น</div><div class="stat">${state.tables.filter(t=>t.status==="playing").length}/${state.tables.length}</div></div><div class="card"><div class="muted">สมาชิก</div><div class="stat">${state.members.length}</div></div><div class="card"><div class="muted">บิลวันนี้</div><div class="stat">${paid.length}</div></div></div><h3 style="margin-top:25px">สถานะโต๊ะ</h3><div class="grid">${state.tables.map(tableCardV2).join("")}</div>`; }
function tableCard(t){ const items=t.items.reduce((s,i)=>s+i.price*i.quantity,0); return `<div class="card table ${t.status}"><h3>${t.name}<span class="badge ${t.status}">${t.status==="playing"?"กำลังเล่น":"ว่าง"}</span></h3>${t.status==="playing"?`<div class="muted">${t.member?`สมาชิก: ${t.member.name}`:"ลูกค้าทั่วไป"}</div><p>เริ่ม ${time(t.startTime)} · ${duration(t.elapsedSeconds)}</p><div class="total">${money(t.currentPrice+items)}</div><small>ค่าโต๊ะ ${money(t.currentPrice)} · POS ${money(items)}</small>`:`<p class="muted">พร้อมใช้งาน</p>`}<div class="actions">${t.status==="free"?`<button data-start="${t.id}">เปิดโต๊ะ</button>`:`<button data-order="${t.id}">เพิ่มรายการ</button><button class="success" data-checkout="${t.id}">คิดเงิน</button>`}<button class="outline" data-relay="${t.id}">${t.relayState==="on"?"ปิด Relay":"เปิด Relay"}</button></div></div>`; }
function tableCardV2(t){ const items=t.items.reduce((sum,item)=>sum+item.price*item.quantity,0), active=t.status!=="free", label={playing:"กำลังเล่น",paused:"พักเวลา",awaiting_payment:"รอชำระเงิน",free:"ว่าง"}[t.status]||t.status; const details=active?`<div class="muted">${t.member?`สมาชิก: ${t.member.name}`:"ลูกค้าทั่วไป"}</div><p>เริ่ม ${time(t.startTime)} · ${duration(t.elapsedSeconds||0)}</p><div class="total">${money((t.currentPrice||0)+items)}</div><small>ค่าโต๊ะ ${money(t.currentPrice)} · POS ${money(items)}</small>`:`<p class="muted">พร้อมใช้งาน</p>`; const actions=t.status==="free"?`<button data-start="${t.id}">เปิดโต๊ะ</button>`:t.status==="playing"?`<button data-order="${t.id}">เพิ่มรายการ</button><button data-pause="${t.id}">พักเวลา</button><button class="success" data-checkout="${t.id}">คิดเงิน</button><button class="danger" data-cancel="${t.id}">ยกเลิก</button>`:t.status==="paused"?`<button data-resume="${t.id}">เล่นต่อ</button><button class="success" data-checkout="${t.id}">คิดเงิน</button><button class="danger" data-cancel="${t.id}">ยกเลิก</button>`:`<span class="muted">รอยืนยันการชำระเงิน</span>`; return `<div class="card table ${t.status}"><h3>${t.name}<span class="badge ${t.status}">${label}</span></h3>${details}<div class="actions">${actions}<button class="outline" data-relay="${t.id}">${t.relayState==="on"?"ปิด Relay":"เปิด Relay"}</button></div></div>`; }
function tables(){ return `<div class="grid">${state.tables.map(tableCardV2).join("")}</div>`; }
function pos(){ const open=state.tables.filter(t=>t.status==="playing"); return `<div class="card"><h3>เลือกโต๊ะเพื่อเพิ่มรายการ</h3>${open.length?`<select id="posTable">${open.map(t=>`<option value="${t.id}">${t.name} — ${t.member?.name||"ลูกค้าทั่วไป"}</option>`).join("")}</select><div class="grid">${state.products.filter(p=>p.active).map(p=>`<div class="card"><b>${p.name}</b><p class="muted">${p.category}</p><div class="total">${money(p.price)}</div><button data-product="${p.id}">+ เพิ่มรายการ</button></div>`).join("")}</div>`:`<p class="muted">ยังไม่มีโต๊ะที่เปิดใช้งาน</p>`}</div><div class="card" style="margin-top:18px"><h3>เพิ่มสินค้า</h3><form id="productForm" class="two"><input name="name" placeholder="ชื่อสินค้า" required><input name="price" type="number" min="0" placeholder="ราคา" required><input name="category" placeholder="หมวดหมู่ เช่น เครื่องดื่ม"><button>บันทึกสินค้า</button></form></div>`; }
function members(){ return `<div class="grid"><div class="card form"><h3>เพิ่มสมาชิก</h3><form id="memberForm"><label>ชื่อ</label><input name="name" required><label>โทรศัพท์</label><input name="phone"><label>แต้มเริ่มต้น</label><input name="points" type="number" value="0"><label>หมายเหตุ</label><input name="note"><button>บันทึกสมาชิก</button></form></div><div class="card"><h3>รายชื่อสมาชิก (${state.members.length})</h3>${state.members.length?`<table><tr><th>รหัส</th><th>ชื่อ</th><th>โทรศัพท์</th><th>แต้ม</th></tr>${state.members.map(m=>`<tr><td>${m.code}</td><td>${m.name}</td><td>${m.phone||"-"}</td><td>${m.points}</td></tr>`).join("")}</table>`:`<p class="muted">ยังไม่มีข้อมูลสมาชิก</p>`}</div></div>`; }
function bills(){ const result=billHistory||{items:state.bills,pagination:{page:1,total:state.bills.length,totalPages:1}}; const method=b=>b.paymentMethod==="transfer"?"โอนเงิน":b.paymentMethod==="qr"?"QR Payment":"เงินสด"; const label=b=>b.status==="paid"?"ชำระแล้ว":b.status==="void"?"ยกเลิก": "รอชำระ"; return `<div class="card"><h3>ประวัติบิล</h3><form id="billSearchForm" class="two"><input name="receipt" placeholder="ค้นหาเลขใบเสร็จ"><input name="table" placeholder="ค้นหาโต๊ะ / หมายเลขโต๊ะ"><input name="from" type="date"><input name="to" type="date"><select name="status"><option value="">ทุกสถานะ</option><option value="paid">ชำระแล้ว</option><option value="void">ยกเลิก</option><option value="awaiting_payment">รอชำระ</option></select><button>ค้นหา</button></form><p class="muted">พบ ${result.pagination.total} บิล · เรียงรายการล่าสุดก่อน</p><table><tr><th>เลขบิล</th><th>เวลา</th><th>โต๊ะ / ลูกค้า</th><th>ยอด</th><th>การชำระ</th><th>สถานะ</th><th></th></tr>${result.items.map(b=>`<tr><td>${escapeHtml(b.receiptNumber||b.number)}</td><td>${new Date(b.createdAt).toLocaleString("th-TH")}</td><td>${escapeHtml(b.tableName)}<br><small>${escapeHtml(b.memberName)}</small></td><td>${money(b.total)}</td><td>${method(b)}</td><td><span class="badge ${b.status}">${label(b)}</span></td><td><div class="actions"><button class="outline" data-bill-details="${b.id}">รายละเอียด</button>${b.status!=="void"?`<button class="danger" data-void-bill="${b.id}">Void</button>`:""}</div></td></tr>`).join("")||`<tr><td colspan="7" class="muted">ไม่พบบิลตามเงื่อนไข</td></tr>`}</table></div>`; }
function reports(){ const a=analytics; const periodInput=reportType==="year"?`<input name="period" type="number" min="2020" max="2100" value="${reportPeriod}" required>`:`<input name="period" type="month" value="${reportPeriod}" required>`; if(reportError)return `<div class="card"><h3>โหลดรายงานไม่สำเร็จ</h3><p class="muted">${escapeHtml(reportError)}</p><button id="retryReports">ลองใหม่</button></div>`; if(!a)return `<div class="card">กำลังโหลดรายงาน…</div>`; const hour=a.peakHour.bills?`${String(a.peakHour.hour).padStart(2,"0")}:00–${String(a.peakHour.hour).padStart(2,"0")}:59`:"ยังไม่มีข้อมูล"; const weekday=a.peakWeekday.bills?a.peakWeekday.name:"ยังไม่มีข้อมูล"; const max=Math.max(...a.daily.map(x=>x.revenue),1); return `<div class="card"><form id="reportFilter" class="two"><select name="type" id="reportType"><option value="month" ${reportType==="month"?"selected":""}>รายเดือน</option><option value="year" ${reportType==="year"?"selected":""}>รายปี</option></select>${periodInput}<button>แสดงรายงาน</button></form></div><div class="grid" style="margin-top:18px"><div class="card"><div class="muted">รายได้รวม</div><div class="stat">${money(a.revenue)}</div></div><div class="card"><div class="muted">ค่าโต๊ะ / POS</div><div class="stat">${money(a.tableRevenue)} / ${money(a.posRevenue)}</div></div><div class="card"><div class="muted">จำนวนบิล / ยอดเฉลี่ย</div><div class="stat">${a.billCount} / ${money(a.averageBill)}</div></div><div class="card"><div class="muted">ช่วงเวลาลูกค้าเยอะที่สุด</div><div class="stat">${hour}</div><small>${a.peakHour.bills} บิล · ${money(a.peakHour.revenue)}</small></div></div>`; }
function settings(){ const s=state.settings; return `<div class="card form"><h3>ตั้งค่าร้าน</h3><form id="settingsForm"><label>ชื่อร้าน</label><input name="shopName" value="${s.shopName}"><label>อัตราค่าโต๊ะต่อชั่วโมง</label><input name="hourlyRate" type="number" min="0" value="${s.hourlyRate}"><label>ค่าบริการขั้นต่ำ</label><input name="minimumCharge" type="number" min="0" value="${s.minimumCharge}"><label>PromptPay ID (สำหรับแสดงในขั้นต่อไป)</label><input name="promptPayId" value="${s.promptPayId||""}"><button>บันทึก</button></form><p class="muted">การเชื่อม ESP32: ตั้งค่า environment <code>ESP32_BASE_URL</code> แล้วระบบจะเรียก <code>/relay/{channel}?state=on|off</code></p></div>${backupSection()}`; }
function backupSection(){ const list=backups||[]; return `<div class="card" style="margin-top:18px"><h3>สำรองข้อมูล (Backup)</h3><p class="muted">ระบบสำรองข้อมูลอัตโนมัติทุก 24 ชั่วโมง เก็บล่าสุด ${MAX_BACKUPS_LABEL} ชุด และสำรองให้เองก่อนกู้คืนทุกครั้ง</p><button id="backupNow">สำรองข้อมูลตอนนี้</button><table style="margin-top:14px"><tr><th>วันที่สำรอง</th><th>ขนาดไฟล์</th><th></th></tr>${list.length?list.map(b=>`<tr><td>${new Date(b.createdAt).toLocaleString("th-TH")}</td><td>${(b.size/1024).toFixed(1)} KB</td><td><div class="actions"><button class="outline" data-backup-download="${b.file}">ดาวน์โหลด</button><button data-backup-restore="${b.file}">กู้คืน</button><button class="danger" data-backup-delete="${b.file}">ลบ</button></div></td></tr>`).join(""):`<tr><td colspan="3" class="muted">ยังไม่มีข้อมูลสำรอง</td></tr>`}</table></div>`; }
const MAX_BACKUPS_LABEL = 30;
function openModal(html){ $("#modalBody").innerHTML=html; $("#modal").classList.remove("hidden"); } function closeModal(){ $("#modal").classList.add("hidden"); } $("#closeModal").onclick=closeModal;
function bind(){ document.querySelectorAll("[data-start]").forEach(b=>b.onclick=()=>startDialog(b.dataset.start)); document.querySelectorAll("[data-order]").forEach(b=>b.onclick=()=>orderDialog(b.dataset.order)); document.querySelectorAll("[data-checkout]").forEach(b=>b.onclick=()=>checkoutDialog(b.dataset.checkout)); document.querySelectorAll("[data-relay]").forEach(b=>b.onclick=()=>relay(b.dataset.relay)); document.querySelectorAll("[data-product]").forEach(b=>b.onclick=()=>addProduct(b.dataset.product)); document.querySelectorAll("[data-print-bill]").forEach(b=>b.onclick=()=>printBill(b.dataset.printBill)); document.querySelectorAll("[data-delete-bill]").forEach(b=>b.onclick=()=>deleteBill(b.dataset.deleteBill)); $("#memberForm") && ($("#memberForm").onsubmit=submitMember); $("#productForm") && ($("#productForm").onsubmit=submitProduct); $("#settingsForm") && ($("#settingsForm").onsubmit=submitSettings); $("#reportFilter") && ($("#reportFilter").onsubmit=applyReportFilter); $("#reportType") && ($("#reportType").onchange=e=>{ reportType=e.target.value; reportPeriod=reportType==="year"?String(new Date().getFullYear()):new Date().toISOString().slice(0,7); render(); }); $("#backupNow") && ($("#backupNow").onclick=createBackup); document.querySelectorAll("[data-backup-download]").forEach(b=>b.onclick=()=>{ window.open(`/api/backups/${encodeURIComponent(b.dataset.backupDownload)}/download`, "_blank"); }); document.querySelectorAll("[data-backup-restore]").forEach(b=>b.onclick=()=>restoreBackup(b.dataset.backupRestore)); document.querySelectorAll("[data-backup-delete]").forEach(b=>b.onclick=()=>deleteBackup(b.dataset.backupDelete)); }
const bindLegacyControls = bind;
bind = function(){ bindLegacyControls(); document.querySelectorAll("[data-pause]").forEach(button=>button.onclick=()=>tableSessionAction(button.dataset.pause,"pause")); document.querySelectorAll("[data-resume]").forEach(button=>button.onclick=()=>tableSessionAction(button.dataset.resume,"resume")); document.querySelectorAll("[data-cancel]").forEach(button=>button.onclick=()=>tableSessionAction(button.dataset.cancel,"cancel")); };
const bindSprint4Controls = bind;
bind = function(){ bindSprint4Controls(); $("#billSearchForm") && ($("#billSearchForm").onsubmit=searchBills); document.querySelectorAll("[data-bill-details]").forEach(button=>button.onclick=()=>viewBillDetails(button.dataset.billDetails)); document.querySelectorAll("[data-void-bill]").forEach(button=>button.onclick=()=>voidBillDialog(button.dataset.voidBill)); applyPermissionVisibility(); };
function applyPermissionVisibility(){ if(!state?.user) return; const allowed={OWNER:["start","pause","resume","checkout","void"],MANAGER:["start","pause","resume","checkout","void"],CASHIER:["start","checkout"],STAFF:["start","pause","resume"]}[state.user.role]||[]; [["[data-start]","start"],["[data-pause]","pause"],["[data-resume]","resume"],["[data-checkout]","checkout"],["[data-void-bill]","void"]].forEach(([selector,key])=>{if(!allowed.includes(key)) document.querySelectorAll(selector).forEach(button=>button.remove());}); if(!["OWNER","MANAGER"].includes(state.user.role)) document.querySelector('aside button[data-page="reports"]')?.remove(); if(state.user.role!=="OWNER") document.querySelector('aside button[data-page="settings"]')?.remove(); }
async function loadBillHistory(query=""){ try { billHistory=await api(`/api/bills${query?`?${query}`:""}`); } catch(e) { notify(e.message,true); } }
async function searchBills(event){ event.preventDefault(); const params=new URLSearchParams(Object.fromEntries(new FormData(event.target))); params.set("page", "1"); params.set("pageSize", "50"); await loadBillHistory(params.toString()); render(); }
async function viewBillDetails(id){ try{ const data=await api(`/api/bills/${id}`); const b=data.bill, snapshot=b.pricingSnapshot||{}; const events=data.auditEvents.map(e=>`<li>${new Date(e.occurredAt).toLocaleString("th-TH")} — ${escapeHtml(e.event)} <small>(${escapeHtml(e.actorId||e.userId||"UNKNOWN")})</small></li>`).join("")||"<li>ไม่มี Audit Event ที่เชื่อมโยง</li>"; const payments=data.payments.map(p=>`${p.method||"qr"}: ${money(p.amount)} (${p.status}) ${p.paidAt?new Date(p.paidAt).toLocaleString("th-TH"):""}`).join("<br>")||"ยังไม่มีข้อมูลการชำระ"; openModal(`<h3>รายละเอียดบิล ${escapeHtml(b.receiptNumber||b.number)}</h3><p>โต๊ะ: <b>${escapeHtml(b.tableName)}</b><br>เริ่ม: ${b.playStartedAt?new Date(b.playStartedAt).toLocaleString("th-TH"):"-"}<br>สิ้นสุด: ${b.playEndedAt?new Date(b.playEndedAt).toLocaleString("th-TH"):"-"}<br>ระยะเวลา: ${Number.isFinite(b.playDurationSeconds)?duration(b.playDurationSeconds):"-"}</p><p>ราคาที่ใช้: ${snapshot.rateSatang?money(snapshot.rateSatang/100)+" / ชั่วโมง":"ไม่มี Snapshot"}<br>ก่อนปัด: ${money(((b.playAmountSatang||0)+(b.foodAmountSatang||0))/100)}<br>ยอดหลังปัด: <b>${money(b.total)}</b></p><p>วิธีชำระ / เวลาได้รับเงิน:<br>${payments}</p>${b.status==="void"?`<p class="danger">Void: ${escapeHtml(b.voidReason||"-")} (${escapeHtml(b.voidedBy||"UNKNOWN")})</p>`:""}<h4>Audit Events</h4><ul>${events}</ul></div>`); }catch(e){notify(e.message,true);} }
function voidBillDialog(id){ const bill=(billHistory?.items||state.bills).find(item=>item.id===id); if(!bill) return; openModal(`<h3>Void บิล ${escapeHtml(bill.receiptNumber||bill.number)}</h3><p class="muted">ข้อมูลบิลและการชำระจะไม่ถูกลบ</p><label>เหตุผลการ Void</label><textarea id="voidReason" required></textarea><button class="danger" id="confirmVoid">ยืนยัน Void</button>`); $("#confirmVoid").onclick=async()=>{ const reason=$("#voidReason").value.trim(); if(!reason) return notify("กรุณาระบุเหตุผลการ Void",true); try{const result=await api(`/api/bills/${id}`,{method:"DELETE",body:JSON.stringify({reason,actorId:"SYSTEM"})}); closeModal(); await refresh(); await loadBillHistory(); render(); notify(result.message);}catch(e){notify(e.message,true);} }; }
async function tableSessionAction(tableId, action){ if(action==="cancel"&&!confirm("ยืนยันยกเลิก Session นี้? จะไม่สร้างยอดขาย")) return; try{ const result=await api(`/api/tables/${tableId}/${action}`,{method:"POST",body:"{}"}); await refresh(); notify(result.warning||({pause:"พักเวลาแล้ว",resume:"เล่นต่อแล้ว",cancel:"ยกเลิก Session แล้ว"}[action]),!!result.warning); }catch(error){ notify(error.message,true); } }
async function createBackup(){ try{ await api("/api/backups",{method:"POST"}); await loadBackups(); render(); notify("สำรองข้อมูลสำเร็จ"); }catch(e){ notify(e.message,true); } }
async function restoreBackup(file){ if(!confirm(`ยืนยันกู้คืนข้อมูลจากไฟล์นี้?\nข้อมูลปัจจุบันจะถูกแทนที่ (ระบบจะสำรองข้อมูลปัจจุบันไว้ให้ก่อน)`)) return; try{ const result=await api(`/api/backups/${encodeURIComponent(file)}/restore`,{method:"POST"}); await refresh(); await loadBackups(); analytics=null; render(); notify(result.message); }catch(e){ notify(e.message,true); } }
async function deleteBackup(file){ if(!confirm(`ยืนยันลบไฟล์สำรองข้อมูลนี้?`)) return; try{ const result=await api(`/api/backups/${encodeURIComponent(file)}`,{method:"DELETE"}); await loadBackups(); render(); notify(result.message); }catch(e){ notify(e.message,true); } }
async function loadAnalytics(){ try { reportError=null; analytics=await api(`/api/reports/analytics?type=${encodeURIComponent(reportType)}&period=${encodeURIComponent(reportPeriod)}`); } catch(e) { analytics=null; reportError=e.message||"ไม่สามารถโหลดรายงานได้"; } }
async function applyReportFilter(e){ e.preventDefault(); const d=Object.fromEntries(new FormData(e.target)); reportType=d.type; reportPeriod=d.period; analytics=null; render(); await loadAnalytics(); render(); }
function startDialog(id){ openModal(`<h3>เปิด ${state.tables.find(t=>t.id==id).name}</h3><label>ผูกสมาชิก (ไม่บังคับ)</label><select id="memberChoice"><option value="">ลูกค้าทั่วไป</option>${state.members.map(m=>`<option value="${m.id}">${m.code} — ${m.name}</option>`).join("")}</select><button id="confirmStart">เริ่มจับเวลาและเปิด Relay</button>`); $("#confirmStart").onclick=async()=>{try{const data=await api(`/api/tables/${id}/start`,{method:"POST",body:JSON.stringify({memberId:$("#memberChoice").value||null})});closeModal();await refresh();notify(data.warning||"เปิดโต๊ะและสั่งเปิด Relay แล้ว",!!data.warning);}catch(e){notify(e.message,true)}}; }
function orderDialog(id){ const t=state.tables.find(t=>t.id==id); openModal(`<h3>${t.name}: รายการปัจจุบัน</h3>${t.items.map(i=>`<div class="item"><span>${i.name} × ${i.quantity}</span><b>${money(i.price*i.quantity)}</b></div>`).join("")||"<p class=muted>ยังไม่มีรายการ</p>"}<p class="muted">ใช้ปุ่ม “เพิ่มรายการ” หรือเมนู POS เพื่อเพิ่มสินค้า</p>`); }
function checkoutDialog(id){ const t=state.tables.find(t=>t.id==id), food=t.items.reduce((s,i)=>s+i.price*i.quantity,0); openModal(`<h3>คิดเงิน ${t.name}</h3><p>ค่าโต๊ะ: ${money(t.currentPrice)}<br>อาหาร/เครื่องดื่ม: ${money(food)}</p><div class="total">รวมโดยประมาณ ${money(t.currentPrice+food)}</div><div class="actions"><button id="cash">เงินสด</button><button id="transfer">โอนเงิน</button></div>`); $("#cash").onclick=()=>checkout(id,"cash"); $("#transfer").onclick=()=>checkout(id,"transfer"); }
async function checkout(id,method){ try{const data=await api(`/api/tables/${id}/checkout`,{method:"POST",body:JSON.stringify({paymentMethod:method})}); openModal(`<h3>ยืนยันรับชำระ</h3><p>บิล <b>${data.bill.number}</b></p><p>วิธีชำระ: ${method==="transfer"?"โอนเงิน":"เงินสด"}</p><div class="total">ยอดรับชำระ ${money(data.payment.amount)}</div><p class="muted">โต๊ะจะถูกปิดหลังยืนยันการชำระเงิน</p><div class="actions"><button id="confirmPay">ยืนยันรับชำระ</button><button class="outline" id="cancelPay">ยกเลิกรายการชำระ</button></div>`); $("#confirmPay").onclick=async()=>{try{const confirmed=await api(`/api/payments/${data.payment.id}/confirm`,{method:"POST"});closeModal();await refresh();notify(confirmed.warning||"ชำระเงินแล้วและปิด Relay",!!confirmed.warning);offerPrint(data.bill.id);}catch(e){notify(e.message,true);}}; $("#cancelPay").onclick=async()=>{try{await api(`/api/payments/${data.payment.id}/cancel`,{method:"POST"});closeModal();await refresh();notify("ยกเลิกรายการชำระแล้ว");}catch(e){notify(e.message,true);}};}catch(e){notify(e.message,true)} }
async function deleteBill(id){ const bill=state.bills.find(b=>b.id===id); if(!bill || !confirm(`ยืนยันยกเลิกบิล ${bill.number}?\nข้อมูลเดิมจะถูกเก็บไว้ในประวัติการตรวจสอบ`)) return; try { const result=await api(`/api/bills/${id}`,{method:"DELETE"}); analytics=null; await refresh(); notify(result.message); } catch(e) { notify(e.message,true); } }
function escapeHtml(value){ return String(value??"").replace(/[&<>'"]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;","\"":"&quot;"})[char]); }
function offerPrint(billId){ const bill=state.bills.find(b=>b.id===billId); if(!bill) return; openModal(`<h3>ชำระเงินสำเร็จ</h3><p>บิล <b>${bill.number}</b> ยอด ${money(bill.total)}</p><p>ต้องการพิมพ์ใบเสร็จให้ลูกค้าหรือไม่?</p><div class="actions"><button id="printNow">พิมพ์ใบเสร็จ</button><button class="outline" id="skipPrint">ไม่พิมพ์ตอนนี้</button></div>`); $("#printNow").onclick=()=>{closeModal();printBill(billId);}; $("#skipPrint").onclick=closeModal; }
function printBill(id){ const bill=state.bills.find(b=>b.id===id); if(!bill) return; const popup=window.open("","receipt","width=420,height=700"); if(!popup){ notify("เบราว์เซอร์บล็อกหน้าต่างพิมพ์ กรุณาอนุญาตป๊อปอัป",true); return; } const items=(bill.items||[]).map(i=>`<tr><td>${escapeHtml(i.name)} × ${i.quantity}</td><td class="right">${money(i.total)}</td></tr>`).join("")||"<tr><td colspan=\"2\" class=\"small\">ไม่มีรายการอาหาร/เครื่องดื่ม</td></tr>"; const payment=bill.paymentMethod==="transfer"?"โอนเงิน":bill.paymentMethod==="qr"?"QR Payment":"เงินสด"; const start=bill.playStartedAt?new Date(bill.playStartedAt).toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit",second:"2-digit"}):"-"; const end=bill.playEndedAt?new Date(bill.playEndedAt).toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit",second:"2-digit"}):"-"; const played=Number.isFinite(bill.playDurationSeconds)?duration(bill.playDurationSeconds):"-"; popup.document.write(`<!doctype html><html lang="th"><head><meta charset="utf-8"><title>ใบเสร็จ ${escapeHtml(bill.number)}</title><style>@page{size:80mm auto;margin:4mm}*{box-sizing:border-box}body{width:72mm;margin:0;font-family:Arial,"Tahoma",sans-serif;color:#000;font-size:12px}.center{text-align:center}.right{text-align:right}h2{font-size:17px;margin:0 0 4px}.line{border-top:1px dashed #000;margin:9px 0}table{width:100%;border-collapse:collapse}td{padding:3px 0}.total{font-weight:bold;font-size:15px}.small{font-size:10px}@media print{body{width:72mm}}</style></head><body><div class="center"><h2>${escapeHtml(state.settings.shopName)}</h2><div>ใบเสร็จรับเงิน</div><div class="small">เลขที่ ${escapeHtml(bill.number)}</div></div><div class="line"></div><table><tr><td>วันที่</td><td class="right">${new Date(bill.createdAt).toLocaleString("th-TH")}</td></tr><tr><td>โต๊ะ</td><td class="right">${escapeHtml(bill.tableName)}</td></tr><tr><td>ลูกค้า</td><td class="right">${escapeHtml(bill.memberName)}</td></tr><tr><td>เริ่มเล่น</td><td class="right">${start}</td></tr><tr><td>หยุดเล่น</td><td class="right">${end}</td></tr><tr><td>เวลาเล่นรวม</td><td class="right">${played}</td></tr></table><div class="line"></div><table>${items}<tr><td>ค่าเวลาโต๊ะ</td><td class="right">${money(bill.playAmount)}</td></tr><tr><td>อาหาร/เครื่องดื่ม</td><td class="right">${money(bill.foodAmount)}</td></tr></table><div class="line"></div><table class="total"><tr><td>รวมทั้งสิ้น</td><td class="right">${money(bill.total)}</td></tr><tr class="small"><td>ชำระโดย</td><td class="right">${payment}</td></tr></table><div class="line"></div><div class="center small">ขอบคุณที่ใช้บริการ</div><script>window.onload=()=>{window.focus();window.print();};<\/script></body></html>`); popup.document.close(); }
async function relay(id){const t=state.tables.find(t=>t.id==id);try{const r=await api(`/api/relay/${id}`,{method:"POST",body:JSON.stringify({state:t.relayState==="on"?"off":"on"})});await refresh();notify(r.warning||r.message);}catch(e){notify(e.message,true)}}
async function addProduct(productId){const tableId=$("#posTable")?.value;if(!tableId)return;try{await api(`/api/tables/${tableId}/items`,{method:"POST",body:JSON.stringify({productId})});await refresh();notify("เพิ่มรายการแล้ว");}catch(e){notify(e.message,true)}}
async function submitMember(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await api("/api/members",{method:"POST",body:JSON.stringify(d)});e.target.reset();await refresh();notify("เพิ่มสมาชิกแล้ว");}catch(x){notify(x.message,true)}} async function submitProduct(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await api("/api/products",{method:"POST",body:JSON.stringify(d)});await refresh();notify("เพิ่มสินค้าแล้ว");}catch(x){notify(x.message,true)}} async function submitSettings(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.hourlyRate=Number(d.hourlyRate);d.minimumCharge=Number(d.minimumCharge);try{await api("/api/settings",{method:"PUT",body:JSON.stringify(d)});await refresh();notify("บันทึกการตั้งค่าแล้ว");}catch(x){notify(x.message,true)}}
function tickPlayingTables(){
  if(!state || !state.tables.some(t=>t.status==="playing")) return;
  state.tables.forEach(t=>{
    if(t.status!=="playing") return;
    t.elapsedSeconds++;
  });
  if(page==="dashboard" || page==="tables") render();
}
let staffUsers=[], activeSessions=[];
async function loadStaff(){const r=await api("/api/users");staffUsers=r.users;}
async function loadSessions(){const r=await api("/api/sessions");activeSessions=r.sessions;}
function staff(){const rows=staffUsers.map(u=>`<tr><td>${escapeHtml(u.username)}</td><td>${escapeHtml(u.displayName)}</td><td><span class="badge">${u.role}</span></td><td><span class="status-badge ${u.status==="ACTIVE"?"status-active":"status-disabled"}">${u.status==="ACTIVE"?"🟢 ACTIVE":"🔴 DISABLED"}</span></td><td>${u.lastLoginAt?new Date(u.lastLoginAt).toLocaleString("th-TH"):"-"}</td><td>${u.failedLoginCount||0}</td><td><button data-edit-user="${u.userId}">แก้ไข</button><button data-reset-user="${u.userId}">Reset</button><button class="danger" data-status-user="${u.userId}" data-status="${u.status==="ACTIVE"?"DISABLED":"ACTIVE"}">${u.status==="ACTIVE"?"Disable":"Enable"}</button></td></tr>`).join("")||`<tr><td colspan="7" class="muted">ไม่พบพนักงาน</td></tr>`;return `<div class="card"><div class="actions"><h3>จัดการพนักงาน</h3><button id="addStaff">เพิ่มพนักงาน</button></div><input id="staffSearch" placeholder="ค้นหา Username หรือชื่อ"><table><tr><th>Username</th><th>Display Name</th><th>Role</th><th>Status</th><th>Last Login</th><th>Failed</th><th></th></tr>${rows}</table></div>`;}
function sessions(){return `<div class="card"><h3>Active Sessions</h3>${activeSessions.length?`<table><tr><th>User</th><th>Login</th><th>Last Activity</th><th>เหลือเวลา</th><th></th></tr>${activeSessions.map(s=>`<tr><td>${s.userId}</td><td>${new Date(s.loginTime).toLocaleString("th-TH")}</td><td>${new Date(s.lastActivity).toLocaleString("th-TH")}</td><td>${Math.ceil(s.remainingMs/60000)} นาที</td><td>${state.user.role==="OWNER"?`<button class="danger" data-revoke-session="${s.id}">Force Logout</button>`:""}</td></tr>`).join("")}</table>`:`<p class="muted">ไม่มี Session ที่ใช้งาน</p>`}</div>`;}
function account(){return `<div class="card form"><h3>บัญชีของฉัน</h3><p>${escapeHtml(state.user.displayName)} · ${escapeHtml(state.user.username)} · ${state.user.role}</p><form id="myPassword"><label>รหัสผ่านเดิม</label><input name="currentPassword" type="password" required><label>รหัสผ่านใหม่</label><input name="password" type="password" minlength="8" required><small>รหัสผ่านต้องมีความยาวอย่างน้อย 8 ตัว</small><label class="password-toggle"><input id="showMyPasswords" type="checkbox"> แสดงรหัสผ่าน</label><button>เปลี่ยนรหัสผ่าน</button></form></div>`;}
const oldNav=nav, oldRender=render, oldBind=bind;
nav=function(){document.querySelectorAll('aside button[data-page]').forEach(button=>button.onclick=async()=>{page=button.dataset.page;try{if(page==="reports")await loadAnalytics();if(page==="bills")await loadBillHistory();if(page==="settings")await loadBackups();if(page==="staff")await loadStaff();if(page==="sessions")await loadSessions();if(page==="products")await loadInventory();render();}catch(e){notify(e.message,true);render();}});$("#refresh").onclick=refresh;$("#logout").onclick=async()=>{await api("/api/auth/logout",{method:"POST"});state=null;showLogin();};};
render=function(){if(!state)return;const names={dashboard:"ภาพรวม",tables:"โต๊ะสนุกเกอร์",pos:"POS",products:"จัดการสินค้า",members:"สมาชิก",bills:"ประวัติบิล",reports:"รายงาน",settings:"ตั้งค่า",staff:"จัดการพนักงาน",sessions:"Active Sessions",account:"บัญชีของฉัน"};$("#title").textContent=names[page];$("#clock").textContent=new Date().toLocaleString("th-TH");$("#currentUser").textContent=`${state.user.displayName} (${state.user.role})`;const canManageProducts=["OWNER","MANAGER"].includes(state.user.role);$("#productsNav").classList.toggle("hidden",!canManageProducts);if(page==="products"&&!canManageProducts)page="dashboard";const pages={dashboard,tables,pos,products,members,bills,reports,settings,staff,sessions,account};$("#app").innerHTML=pages[page]();bind();};
bind=function(){oldBind();$("#addStaff")&&($("#addStaff").onclick=()=>staffDialog());$("#myPassword")&&($("#myPassword").onsubmit=e=>passwordSubmit(e,state.user.userId));$("#showMyPasswords")&&bindPasswordVisibility("#showMyPasswords","#myPassword");$("#retryReports")&&($("#retryReports").onclick=async()=>{await loadAnalytics();render();});document.querySelectorAll("[data-edit-user]").forEach(b=>b.onclick=()=>staffDialog(staffUsers.find(u=>u.userId===b.dataset.editUser)));document.querySelectorAll("[data-reset-user]").forEach(b=>b.onclick=()=>resetDialog(b.dataset.resetUser));document.querySelectorAll("[data-status-user]").forEach(b=>b.onclick=()=>statusUser(b.dataset.statusUser,b.dataset.status));document.querySelectorAll("[data-revoke-session]").forEach(b=>b.onclick=()=>revokeSession(b.dataset.revokeSession));};
function staffDialog(u){openModal(`<h3>${u?"แก้ไข":"เพิ่ม"} พนักงาน</h3><form id="staffForm"><input name="username" placeholder="Username" value="${u?.username||""}" required><input name="displayName" placeholder="Display Name" value="${u?.displayName||""}" required><select name="role">${["OWNER","MANAGER","CASHIER","STAFF"].map(r=>`<option ${u?.role===r?"selected":""}>${r}</option>`).join("")}</select>${u?"":`<input name="password" type="password" placeholder="รหัสชั่วคราว" required>`}<button>บันทึก</button></form>`);$("#staffForm").onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(/\s/.test(d.username))return notify("Username ห้ามมีช่องว่าง",true);try{await api(u?`/api/users/${u.userId}`:"/api/users",{method:u?"PATCH":"POST",body:JSON.stringify(d)});closeModal();await loadStaff();render();notify("บันทึกสำเร็จ");}catch(x){notify(x.message,true);}};}
function confirmAction({title,description,onConfirm}){openModal(`<h3>${escapeHtml(title)}</h3><p>${escapeHtml(description)}</p><div class="actions"><button class="outline" id="modalCancel">ยกเลิก</button><button class="danger" id="modalConfirm">ยืนยัน</button></div><p id="modalError" class="danger"></p>`);$("#modalCancel").onclick=closeModal;$("#modalConfirm").onclick=async()=>{const b=$("#modalConfirm");b.disabled=true;b.textContent="กำลังดำเนินการ…";try{await onConfirm();closeModal();}catch(e){$("#modalError").textContent=e.message;b.disabled=false;b.textContent="ยืนยัน";}};}
async function statusUser(id,status){const user=staffUsers.find(u=>u.userId===id);confirmAction({title:status==="DISABLED"?"ปิดการใช้งานผู้ใช้":"เปิดการใช้งานผู้ใช้",description:`${user?.username||id} จะถูก ${status==="DISABLED"?"ปิดการใช้งาน":"เปิดการใช้งาน"}`,onConfirm:async()=>{await api(`/api/users/${id}/status`,{method:"PATCH",body:JSON.stringify({status})});await loadStaff();render();}});}
function resetDialog(id){openModal(`<h3>Reset Password</h3><form id="resetPasswordForm"><input id="resetPassword" name="password" type="password" placeholder="รหัสชั่วคราว"><label class="password-toggle"><input id="showResetPassword" type="checkbox"> แสดงรหัสผ่าน</label><button id="doReset">Reset</button></form>`);bindPasswordVisibility("#showResetPassword","#resetPasswordForm");$("#resetPasswordForm").onsubmit=async e=>{e.preventDefault();try{await api(`/api/users/${id}/password`,{method:"PATCH",body:JSON.stringify({password:$("#resetPassword").value})});notify("รีเซ็ตรหัสแล้ว กรุณาส่งรหัสชั่วคราวอย่างปลอดภัย");closeModal();}catch(e){notify(e.message,true);}};}
async function passwordSubmit(e,id){e.preventDefault();try{await api(`/api/users/${id}/password`,{method:"PATCH",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});notify("เปลี่ยนรหัสผ่านสำเร็จ");e.target.reset();}catch(x){notify(x.message,true);}}
async function revokeSession(id){const target=activeSessions.find(s=>s.id===id);confirmAction({title:"Force Logout",description:`Session ของ ${target?.username||target?.userId||id} จะถูกออกจากระบบทันที`,onConfirm:async()=>{await api(`/api/sessions/${id}`,{method:"DELETE"});await loadSessions();render();}});}
nav(); refresh().catch(e=>notify(e.message,true)); setInterval(tickPlayingTables,1000); setInterval(()=>{ if(state && state.tables.some(t=>t.status==="playing")) refresh(); },15000);
let sessionTimer=null, sessionBusy=false, sessionWarningShown=false, securitySummary=null;
async function monitorSession(){if(!state||sessionBusy)return;sessionBusy=true;try{const status=await api("/api/session/status");if(status.remainingMs<=status.warningMs&&!sessionWarningShown){sessionWarningShown=true;openModal(`<h3>Session ใกล้หมดอายุ</h3><p id="sessionCountdown"></p><div class="actions"><button id="renewSession">ต่ออายุ Session</button><button class="outline" id="logoutSession">ออกจากระบบ</button></div>`);$("#renewSession").onclick=async()=>{await api("/api/session/refresh",{method:"PATCH"});sessionWarningShown=false;closeModal();};$("#logoutSession").onclick=()=>$("#logout").click();}const c=$("#sessionCountdown");if(c)c.textContent=`เหลือเวลา ${Math.ceil(status.remainingMs/60000)} นาที`;}catch(e){if(e.status===401){clearInterval(sessionTimer);sessionTimer=null;closeModal();state=null;showLogin();notify("Session หมดอายุ กรุณาเข้าสู่ระบบใหม่",true);}}finally{sessionBusy=false;}}
function startSessionTimer(){clearInterval(sessionTimer);sessionWarningShown=false;sessionTimer=setInterval(monitorSession,30000);monitorSession();}
const refresh7=refresh;refresh=async function(){await refresh7();if(state)startSessionTimer();};
async function loadSecuritySummary(){try{const [s,u]=await Promise.all([api("/api/sessions"),api("/api/users")]);securitySummary={active:s.sessions.length,online:new Set(s.sessions.map(x=>x.userId)).size,locked:u.users.filter(x=>x.lockedUntil&&new Date(x.lockedUntil)>new Date()).length,disabled:u.users.filter(x=>x.status==="DISABLED").length,error:null};}catch(e){securitySummary={error:e.message};}}
const dashboard7=dashboard;dashboard=function(){const base=dashboard7();if(!["OWNER","MANAGER"].includes(state.user.role))return base;const x=securitySummary;return base+`<div class="grid" style="margin-top:18px"><div class="card"><h3>Security Summary</h3>${!x?"กำลังโหลด…":x.error?`<p class="muted">โหลดไม่ได้: ${escapeHtml(x.error)}</p><button id="refreshSecurity">ลองใหม่</button>`:`<p>Active Sessions: <b>${x.active}</b><br>Online Users: <b>${x.online}</b>${state.user.role==="OWNER"?`<br>Locked: <b>${x.locked}</b><br>Disabled: <b>${x.disabled}</b>`:""}</p>`}</div></div>`;};
const settings7=settings;settings=function(){const base=settings7(),s=state.settings.security;return base+`<div class="card form" style="margin-top:18px"><h3>Security Settings</h3><form id="securityForm"><label>Session Timeout Minutes</label><input name="timeoutMinutes" type="number" min="1" value="${s.timeoutMinutes}"><label>Warning Before Timeout Minutes</label><input name="warningMinutes" type="number" min="0" value="${s.warningMinutes}"><label>Maximum Login Attempts</label><input name="maxLoginAttempts" type="number" min="1" value="${s.maxLoginAttempts}"><label>Account Lock Duration Minutes</label><input name="lockDurationMinutes" type="number" min="1" value="${s.lockDurationMinutes}"><button>บันทึก Security Settings</button></form></div>`;};
const bind7=bind;bind=function(){bind7();bindInventory();$("#securityForm")&&($("#securityForm").onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));Object.keys(d).forEach(k=>d[k]=Number(d[k]));if(d.warningMinutes>=d.timeoutMinutes)return notify("Warning ต้องน้อยกว่า Timeout",true);try{await api("/api/settings/session",{method:"PATCH",body:JSON.stringify(d)});await refresh();notify("บันทึกสำเร็จ");}catch(x){notify(x.message,true);}});$("#refreshSecurity")&&($("#refreshSecurity").onclick=async()=>{await loadSecuritySummary();render();});};
document.addEventListener("visibilitychange",()=>{if(!document.hidden)monitorSession();});

async function loadInventory(){
  try { inventoryError=null; const query=new URLSearchParams({...inventoryFilters,pageSize:100}); const [products,categories]=await Promise.all([api(`/api/products?${query}`),api("/api/product-categories")]); inventoryData={products:products.items,categories:categories.items}; }
  catch(error) { inventoryData=null; inventoryError=error.message||"โหลดข้อมูลสินค้าไม่สำเร็จ"; }
}
function inventoryStockBadge(product){ if(!product.trackStock)return `<span class="badge">ไม่ติดตามสต็อก</span>`; if(product.isOutOfStock)return `<span class="inventory-badge inventory-out">สินค้าหมด</span>`; if(product.isLowStock)return `<span class="inventory-badge inventory-low">ใกล้หมด</span>`; return `<span class="inventory-badge inventory-ok">พร้อมขาย</span>`; }
function products(){
  if(inventoryError)return `<div class="card"><h3>โหลดข้อมูลสินค้าไม่สำเร็จ</h3><p class="muted">${escapeHtml(inventoryError)}</p><button id="retryInventory">ลองใหม่</button></div>`;
  if(!inventoryData)return `<div class="card">กำลังโหลดสินค้า…</div>`;
  const items=inventoryData.products,categories=inventoryData.categories;
  return `<div class="card"><div class="section-head"><h3>สินค้าและสต็อก</h3><div class="actions"><button id="addCategory">เพิ่มหมวดหมู่</button><button id="addInventoryProduct">เพิ่มสินค้า</button></div></div><form id="inventoryFilter" class="inventory-filter"><input name="search" value="${escapeHtml(inventoryFilters.search||"")}" placeholder="ค้นหา SKU หรือชื่อสินค้า"><select name="category"><option value="">ทุกหมวดหมู่</option>${categories.map(category=>`<option value="${category.id}" ${inventoryFilters.category===category.id?"selected":""}>${escapeHtml(category.name)}</option>`).join("")}</select><select name="status"><option value="">ทุกสถานะ</option><option value="ACTIVE" ${inventoryFilters.status==="ACTIVE"?"selected":""}>ACTIVE</option><option value="DISABLED" ${inventoryFilters.status==="DISABLED"?"selected":""}>DISABLED</option></select><label class="checkbox-line"><input type="checkbox" name="lowStock" ${inventoryFilters.lowStock?"checked":""}> ใกล้หมด</label><button>ค้นหา</button></form></div><div class="card inventory-categories"><h3>หมวดหมู่</h3>${categories.map(category=>`<span class="category-chip">${escapeHtml(category.name)} <b>${category.status}</b> <button data-edit-category="${category.id}">แก้ไข</button><button data-category-status="${category.id}" data-status="${category.status==="ACTIVE"?"DISABLED":"ACTIVE"}">${category.status==="ACTIVE"?"ปิด":"เปิด"}</button></span>`).join("")}</div><div class="card inventory-table-wrap"><table><tr><th>SKU</th><th>สินค้า</th><th>หมวดหมู่</th><th>ราคาขาย</th><th>ต้นทุน</th><th>สต็อก</th><th>สถานะ</th><th>จัดการ</th></tr>${items.length?items.map(product=>`<tr><td>${escapeHtml(product.sku||"-")}</td><td><b>${escapeHtml(product.name)}</b><br>${inventoryStockBadge(product)}</td><td>${escapeHtml(product.categoryName||product.category||"อื่น ๆ")}</td><td>${money(product.price)}</td><td>${money(product.cost)}</td><td>${product.trackStock?`${product.stockQuantity} / ต่ำสุด ${product.lowStockThreshold}`:"ไม่ติดตาม"}</td><td><span class="status-badge ${product.status==="ACTIVE"?"status-active":"status-disabled"}">${product.status}</span></td><td><div class="inventory-actions"><button data-edit-product="${product.id}">แก้ไข</button>${product.trackStock?`<button data-receive-product="${product.id}">รับเข้า</button><button data-adjust-product="${product.id}">ปรับสต็อก</button><button data-movements-product="${product.id}">ประวัติ</button>`:""}<button class="${product.status==="ACTIVE"?"danger":"success"}" data-product-status="${product.id}" data-status="${product.status==="ACTIVE"?"DISABLED":"ACTIVE"}">${product.status==="ACTIVE"?"ปิด":"เปิด"}</button></div></td></tr>`).join(""):`<tr><td colspan="8" class="muted">ไม่พบสินค้า</td></tr>`}</table></div>`;
}
function productDialog(product=null){
  const categories=inventoryData?.categories||[];
  openModal(`<h3>${product?"แก้ไขสินค้า":"เพิ่มสินค้า"}</h3><form id="inventoryProductForm" class="form"><label>SKU</label><input name="sku" value="${escapeHtml(product?.sku||"")}" placeholder="ไม่บังคับ"><label>ชื่อสินค้า</label><input name="name" value="${escapeHtml(product?.name||"")}" required><label>หมวดหมู่</label><select name="categoryId"><option value="">อื่น ๆ</option>${categories.filter(category=>category.status==="ACTIVE"||category.id===product?.categoryId).map(category=>`<option value="${category.id}" ${product?.categoryId===category.id?"selected":""}>${escapeHtml(category.name)}</option>`).join("")}</select><label>ราคาขาย</label><input name="price" type="number" min="0" step="0.01" value="${product?.price??0}" required><label>ต้นทุน</label><input name="cost" type="number" min="0" step="0.01" value="${product?.cost??0}" required><label>สถานะ</label><select name="status"><option value="ACTIVE" ${product?.status!=="DISABLED"?"selected":""}>ACTIVE</option><option value="DISABLED" ${product?.status==="DISABLED"?"selected":""}>DISABLED</option></select><label class="checkbox-line"><input name="trackStock" type="checkbox" ${product?.trackStock!==false?"checked":""}> ติดตามสต็อก</label><div id="stockFields">${product?"":`<label>สต็อกเริ่มต้น</label><input name="initialStock" type="number" min="0" step="1" value="0">`}<label>สต็อกขั้นต่ำ</label><input name="lowStockThreshold" type="number" min="0" step="1" value="${product?.lowStockThreshold??0}"></div><button id="saveInventoryProduct">บันทึก</button></form>`);
  const form=$("#inventoryProductForm"),toggle=form.elements.trackStock; toggle.onchange=()=>$("#stockFields").classList.toggle("hidden",!toggle.checked); toggle.onchange();
  form.onsubmit=async event=>{event.preventDefault();const button=$("#saveInventoryProduct");button.disabled=true;const data=Object.fromEntries(new FormData(form));data.trackStock=toggle.checked;try{await api(product?`/api/products/${product.id}`:"/api/products",{method:product?"PATCH":"POST",body:JSON.stringify(data)});closeModal();await loadInventory();render();notify("บันทึกสินค้าแล้ว");}catch(error){notify(error.message,true);button.disabled=false;}};
}
function categoryDialog(category=null){openModal(`<h3>${category?"แก้ไขหมวดหมู่สินค้า":"เพิ่มหมวดหมู่สินค้า"}</h3><form id="inventoryCategoryForm" class="form"><label>ชื่อหมวดหมู่</label><input name="name" value="${escapeHtml(category?.name||"")}" required><label>ลำดับ</label><input name="sortOrder" type="number" min="1" value="${category?.sortOrder??(inventoryData?.categories.length||0)+1}"><button id="saveInventoryCategory">บันทึก</button></form>`);$("#inventoryCategoryForm").onsubmit=async event=>{event.preventDefault();const button=$("#saveInventoryCategory");button.disabled=true;try{await api(category?`/api/product-categories/${category.id}`:"/api/product-categories",{method:category?"PATCH":"POST",body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});closeModal();await loadInventory();render();notify("บันทึกหมวดหมู่แล้ว");}catch(error){notify(error.message,true);button.disabled=false;}};}
function stockDialog(product,receive){openModal(`<h3>${receive?"รับสินค้าเข้า":"ปรับสต็อก"}</h3><p><b>${escapeHtml(product.name)}</b><br>สต็อกปัจจุบัน: ${product.stockQuantity}</p><form id="stockForm" class="form"><label>${receive?"จำนวนที่รับเข้า":"จำนวนที่ปรับ (+/-)"}</label><input name="${receive?"quantity":"quantityChange"}" type="number" ${receive?"min=\"1\"":"step=\"1\""} required><label>เหตุผล${receive?"":" (จำเป็น)"}</label><input name="reason" ${receive?"":"required"}><p id="stockAfter" class="muted"></p><button id="saveStock">บันทึก</button></form>`);const form=$("#stockForm"),input=form.querySelector("input[type=number]"),after=$("#stockAfter");input.oninput=()=>after.textContent=`สต็อกหลังทำรายการ: ${product.stockQuantity+(Number(input.value)||0)}`;form.onsubmit=async event=>{event.preventDefault();const button=$("#saveStock");button.disabled=true;try{await api(`/api/products/${product.id}/stock/${receive?"receive":"adjust"}`,{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(form)))});closeModal();await loadInventory();render();notify("บันทึกสต็อกแล้ว");}catch(error){notify(error.message,true);button.disabled=false;}};}
async function movementDialog(product){try{const result=await api(`/api/products/${product.id}/stock-movements`);openModal(`<h3>ประวัติสต็อก: ${escapeHtml(product.name)}</h3><div class="movement-list">${result.items.length?result.items.map(item=>`<div class="item"><span><b>${item.type}</b><br><small>${new Date(item.createdAt).toLocaleString("th-TH")} · ${escapeHtml(item.reason||"-")}</small></span><span>${item.quantityBefore} → ${item.quantityAfter} (${item.quantityChange>0?"+":""}${item.quantityChange})</span></div>`).join(""):`<p class="muted">ยังไม่มีประวัติสต็อก</p>`}</div>`);}catch(error){notify(error.message,true);}}
function bindInventory(){
  if(!$("#inventoryFilter")){ $("#retryInventory")&&($("#retryInventory").onclick=async()=>{await loadInventory();render();}); return; }
  $("#addInventoryProduct").onclick=()=>productDialog(); $("#addCategory").onclick=categoryDialog;
  $("#inventoryFilter").onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));data.lowStock=event.target.elements.lowStock.checked;inventoryFilters=Object.fromEntries(Object.entries(data).filter(([,value])=>value!==""&&value!==false));await loadInventory();render();};
  document.querySelectorAll("[data-edit-product]").forEach(button=>button.onclick=()=>productDialog(inventoryData.products.find(product=>product.id===button.dataset.editProduct)));
  document.querySelectorAll("[data-edit-category]").forEach(button=>button.onclick=()=>categoryDialog(inventoryData.categories.find(category=>category.id===button.dataset.editCategory)));
  document.querySelectorAll("[data-receive-product]").forEach(button=>button.onclick=()=>stockDialog(inventoryData.products.find(product=>product.id===button.dataset.receiveProduct),true));
  document.querySelectorAll("[data-adjust-product]").forEach(button=>button.onclick=()=>stockDialog(inventoryData.products.find(product=>product.id===button.dataset.adjustProduct),false));
  document.querySelectorAll("[data-movements-product]").forEach(button=>button.onclick=()=>movementDialog(inventoryData.products.find(product=>product.id===button.dataset.movementsProduct)));
  document.querySelectorAll("[data-product-status]").forEach(button=>button.onclick=()=>{const product=inventoryData.products.find(item=>item.id===button.dataset.productStatus),status=button.dataset.status;confirmAction({title:status==="ACTIVE"?"เปิดขายสินค้า":"ปิดขายสินค้า",description:`${product?.name||"สินค้า"} จะถูกตั้งเป็น ${status}`,onConfirm:async()=>{await api(`/api/products/${product.id}/status`,{method:"PATCH",body:JSON.stringify({status})});await loadInventory();render();}});});
  document.querySelectorAll("[data-category-status]").forEach(button=>button.onclick=()=>{const status=button.dataset.status;confirmAction({title:status==="ACTIVE"?"เปิดใช้หมวดหมู่":"ปิดใช้หมวดหมู่",description:"ยืนยันการเปลี่ยนสถานะหมวดหมู่",onConfirm:async()=>{await api(`/api/product-categories/${button.dataset.categoryStatus}/status`,{method:"PATCH",body:JSON.stringify({status})});await loadInventory();render();}});});
}
